#include <vector>
#include <algorithm>
#include <cmath>
#include <numeric>
using namespace std;

class Solution {
public:
    int differenceOfSums(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int min_k = 0, max_k = 0;
        for (int i = 0; i < k; i++) min_k += nums[i];
        for (int i = n - k; i < n; i++) max_k += nums[i];
        return abs(max_k - min_k);
    }
};

import java.util.*;

class Solution {
    public int differenceOfSums(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int minK = 0, maxK = 0;
        for (int i = 0; i < k; i++) minK += nums[i];
        for (int i = n - k; i < n; i++) maxK += nums[i];
        return Math.abs(maxK - minK);
    }
}

var differenceOfSums = function(nums, k) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    let minK = 0, maxK = 0;
    for (let i = 0; i < k; i++) minK += nums[i];
    for (let i = n - k; i < n; i++) maxK += nums[i];
    return Math.abs(maxK - minK);
